args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?filmLabel ?numDirectors ?isTop WHERE {
  {
    SELECT ?film ?filmLabel (COUNT(DISTINCT ?director) AS ?numDirectors) WHERE {
      VALUES ?film { dbr:Fright_Night_2:_New_Blood dbr:23_Blast }
      OPTIONAL { ?film (dbo:director|dbp:director|dbp:directors) ?director . }
      OPTIONAL { ?film rdfs:label ?filmLabel . FILTER (langMatches(lang(?filmLabel), "EN")) }
    }
    GROUP BY ?film ?filmLabel
  }
  {
    SELECT (MAX(?c) AS ?maxCount) WHERE {
      {
        SELECT (COUNT(DISTINCT ?director) AS ?c) WHERE {
          VALUES ?film { dbr:Fright_Night_2:_New_Blood dbr:23_Blast }
          OPTIONAL { ?film (dbo:director|dbp:director|dbp:directors) ?director . }
        }
        GROUP BY ?film
      }
    }
  }
  BIND(IF(?numDirectors = ?maxCount, true, false) AS ?isTop)
}
ORDER BY DESC(?numDirectors)

